using HakutaiKagami.Core.Contracts;
using Xunit;
namespace HakutaiKagami.Tests;
public sealed class NewGameFlowBoundaryTests
{
    [Fact]public void LocalJobNeedsOpeningAndConsentAndReturnsPhysically(){var s=NewGameWorldTests.Session();var w=s.DiagnosticSnapshot();var i=NewGameWorld.LocalWork(w,"request:local");Assert.Equal(ResultCode.Accepted,s.Submit(i,s.Revision).Code);NewGameWorldTests.At(s,2);var t=s.DiagnosticSnapshot().Tasks.Single();Assert.Null(t.StartedAt);Assert.Empty(s.GetActorView(s.PlayerControl).Tasks);var sealedLetter=s.GetActorView(s.PlayerControl).Messages.Single();Assert.True(sealedLetter.Sealed);Assert.Null(sealedLetter.KnownBody);s.Open(s.PlayerControl,sealedLetter.Id,s.Revision);Assert.Equal(AgreementPhase.AwaitingAssent,s.DiagnosticSnapshot().Tasks.Single().Agreement);s.Assent(t.Id,s.PlayerControl,true,s.Revision);NewGameWorldTests.At(s,12);Assert.Equal(ExecutionPhase.Completed,s.DiagnosticSnapshot().Tasks.Single().Execution);Assert.Equal(ReportingPhase.KnownByRecipient,s.DiagnosticSnapshot().Tasks.Single().Report);Assert.Contains(s.GetActorView(i.Actor).Messages,m=>m.KnownBody!=null);}
    [Fact]public void DeclinedLocalWorkDoesNotRun(){var s=NewGameWorldTests.Session();s.Submit(NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:local"),s.Revision);NewGameWorldTests.At(s,2);s.Open(s.PlayerControl,s.GetActorView(s.PlayerControl).Messages.Single().Id,s.Revision);s.Assent(s.DiagnosticSnapshot().Tasks.Single().Id,s.PlayerControl,false,s.Revision);NewGameWorldTests.At(s,10);Assert.Null(s.DiagnosticSnapshot().Tasks.Single().StartedAt);Assert.Equal(ExecutionPhase.Stopped,s.DiagnosticSnapshot().Tasks.Single().Execution);}
    [Fact]public void NoRemoteNpcWorkAtAnotherTown(){var s=NewGameWorldTests.Session([NewGameWorldTests.Officer(site:"site:kofu")]);var i=NewGameWorld.LocalWork(s.DiagnosticSnapshot(),"request:local");Assert.Equal("person:shingen",i.Actor.Value);var wrong=i with{Actor=new("person:nobunaga")};Assert.Equal(ResultCode.InvalidInput,s.Submit(wrong,s.Revision).Code);}
    [Fact]public void MinorAndAppearanceMetadataSurviveRoundTrip(){var setup=NewGameWorldTests.Setup([NewGameWorldTests.Officer() with{BirthYear=1550}]);var w=NewGameWorld.Create(setup.World,setup.Registered,"person:shingen");var copy=ContractJson.Read<ContractWorld>(ContractJson.Write(w));ContractValidation.Validate(copy);Assert.Equal(ContractJson.Write(w),ContractJson.Write(copy));}
    [Fact]public void StartProfileAndProgressSurviveLibraryEdit(){var setup=NewGameWorldTests.Setup();string folder=Path.Combine(Path.GetTempPath(),"hakutai-campaign-tests",Guid.NewGuid().ToString("N"));var store=new NewCampaignStore(folder);var p=store.New(setup.World,setup.Registered,"created:test",123);var session=new WorldSession(NewCampaignStore.Build(p));store.Saves(p).Save(session,"manual",session.DiagnosticSnapshot().WorldId);setup.Registered[0]=setup.Registered[0] with{Name="後日の編集"};var list=store.List(out int unreadable);Assert.Equal(0,unreadable);Assert.Single(list);Assert.Equal("鏡山 宗久",NewCampaignStore.Build(store.Read(p.Instance)).Definitions.Characters.Single(c=>c.Id.Value==p.Selected).Name);}
    [Fact]public void CorruptStartIsListedAsUnreadableAndKept(){string folder=Path.Combine(Path.GetTempPath(),"hakutai-campaign-tests",Guid.NewGuid().ToString("N"));var setup=NewGameWorldTests.Setup();var store=new NewCampaignStore(folder);var p=store.New(setup.World,setup.Registered,"created:test",1);string file=Path.Combine(store.DirectoryFor(p.Instance),"start.json");File.WriteAllText(file,"broken");Assert.Empty(store.List(out int unreadable));Assert.Equal(1,unreadable);Assert.Equal("broken",File.ReadAllText(file));}
    [Theory][InlineData("../escape")][InlineData("not-an-instance")]
    public void CampaignPathCannotEscapeRoot(string id){Assert.Throws<InvalidDataException>(()=>new NewCampaignStore(Path.GetTempPath()).DirectoryFor(id));}
    [Theory][InlineData("membership")][InlineData("historical-name")][InlineData("site")]
    public void RecomputedDefinitionStillNeedsAReproducibleStart(string change){var setup=NewGameWorldTests.Setup();var w=NewGameWorld.Create(setup.World,setup.Registered,"created:test");var d=w.NewGame!;if(change=="membership")d.Start.People[0]=d.Start.People[0] with{Faction="org:oda"};if(change=="historical-name"){int n=Array.FindIndex(d.Start.People,p=>!p.Created);d.Start.People[n]=d.Start.People[n] with{Name="偽の名前"};}if(change=="site")d.Start.Castles[0]=d.Start.Castles[0] with{Faction="org:hojo"};w.Definitions=w.Definitions with{Version=NewGameWorld.Version(d)};Assert.Throws<InvalidDataException>(()=>ContractValidation.Validate(w));}
    [Fact]public void AGroupCopyKeepsAllAppearanceArraysIndependent(){var p=NewGameWorldTests.Officer();var l=new OfficerLibrary(1,[p],[new("group:a","試作",[])]);var copied=NewGameSetup.CopyToGroup(l,p.Id,"group:a","created:copy");copied.Groups[0].Officers[0].Look!.SkinLinear[0]=.1f;Assert.NotEqual(copied.Groups[0].Officers[0].Look!.SkinLinear[0],p.Look!.SkinLinear[0]);}
}
